/** Read compatibility projection: never changes old artboard IDs, paths, history or HTML. */
export function migrateWorkbench(project){
  const p=copy(project);p.artboards ||= [];p.history ||= [];
  if(p.workbench?.schemaVersion>1)fail('UNSUPPORTED_SCHEMA','This workbench version requires a newer Designer');
  const w=p.workbench={schemaVersion:1,goal:'',requirementsPath:'docs/requirements.md',rulesPath:'docs/rules.md',designs:[],sourceProjects:[],sourceImports:[],files:[],...p.workbench};
  w.designs ||= [];w.files ||= [];w.sourceProjects ||= [];w.sourceImports ||= [];
  const assigned=new Set(w.designs.flatMap(d=>d.pageIds||[]));
  const unassigned=p.artboards.filter(a=>!a.deletedAt&&!assigned.has(a.id));
  if(unassigned.length){
    const legacyId=`d-legacy-${p.id}`;let d=w.designs.find(d=>d.id===legacyId);
    if(!d){d={id:legacyId,name:p.name||'Design',folder:`designs/${slug(p.name||'design')}-${legacyId}`,platform:p.platform||'web',pageIds:[],binding:{mode:'inherit'},createdAt:p.createdAt,updatedAt:p.updatedAt};w.designs.push(d);}
    d.pageIds.push(...unassigned.map(a=>a.id));
  }
  for(const d of w.designs){d.binding ||= {mode:'inherit'};d.pageIds ||= [];for(const a of p.artboards)if(d.pageIds.includes(a.id))a.designId=d.id;}
  for(const a of p.artboards)if(a.htmlPath&&!w.files.some(f=>f.path===a.htmlPath))w.files.push(describe(p.id,a.htmlPath,{type:'page',pageId:a.id,designId:a.designId,sha256:a.contentHash}));
  return p;
}

/** Restore content without rolling operational authorization back with the document. */
export function snapshotContent(current,saved){
  const restored=migrateWorkbench(saved),next=copy(current),currentWorkbench=current.workbench||{};
  for(const key of ['name','description','platform','systemId','systemVersion','canvas','artboards'])if(Object.hasOwn(restored,key))next[key]=copy(restored[key]);
  next.workbench=copy(currentWorkbench);for(const key of ['schemaVersion','goal','requirementsPath','rulesPath','designs','files'])next.workbench[key]=copy(restored.workbench[key]);
  const currentFiles=currentWorkbench.files||[];for(const board of next.artboards){const existing=currentFiles.find(f=>f.pageId===board.id&&!f.removedAt),selected=next.workbench.files.find(f=>f.path===board.htmlPath);if(selected){if(existing)selected.id=existing.id;selected.pageId=board.id;selected.designId=board.designId;selected.sha256=board.contentHash;delete selected.savedFsVersion;next.workbench.files=next.workbench.files.filter(f=>f===selected||f.id!==selected.id);for(const other of next.workbench.files)if(other!==selected&&other.pageId===board.id)delete other.pageId;}}
  for(const file of next.workbench.files){const active=currentFiles.find(f=>f.id===file.id);for(const key of ['readonly','writable','writablePaths'])if(active&&Object.hasOwn(active,key))file[key]=copy(active[key]);}
  next.workbench.fileHistory={...copy(restored.workbench.fileHistory||{}),...copy(currentWorkbench.fileHistory||{})};for(const file of next.workbench.files){const history=next.workbench.fileHistory[file.id];if(history){const cursor=history.entries?.findIndex(e=>e.path===file.path&&(!file.sha256||e.sha256===file.sha256));if(cursor>=0)history.cursor=cursor;}}
  for(const design of next.workbench.designs){const active=currentWorkbench.designs?.find(d=>d.id===design.id);delete design.appliedSystem;if(active?.appliedSystem)design.appliedSystem=copy(active.appliedSystem);}
  return next;
}

